 function detect(){const f=[];OCT.forEach(T=>WKS.forEach((_,w)=>[0,1].forEach(s=>{const n=cell(T.id,w,s);if(!n){f.push({ty:"gap",t:T.id,w,s,text:`${T.n} has no ${slotN[s].toLowerCase()} on call the week of ${wkL(w)}.`,sev:"bad"});return}
  const p=onPTO(n,w);if(p)f.push({ty:"pto",t:T.id,w,s,n,text:`${n} is ${slotN[s].toLowerCase()} for ${T.n} the week of ${wkL(w)} but has ${p.note.toLowerCase()}.`,sev:"bad"});
  if(s===0){const other=OCT.find(o=>o.id!==T.id&&cell(o.id,w,0)===n);if(other&&T.id<other.id)f.push({ty:"dbl",t:T.id,w,s,n,text:`${n} is primary for both ${T.n} and ${other.n} the week of ${wkL(w)}.`,sev:"warn"})}
  if(s===0&&w>=2&&cell(T.id,w-1,0)===n&&cell(T.id,w-2,0)===n)f.push({ty:"fat",t:T.id,w,s,n,text:`${n} would be primary for ${T.n} three weeks in a row.`,sev:"warn"})})));
  f.forEach(x=>{const T=OCT.find(o=>o.id===x.t);const busy=n=>OCT.some(o=>[0,1].some(s=>cell(o.id,x.w,s)===n));const cand=T.m.filter(n=>n!==x.n&&!onPTO(n,x.w)&&!busy(n)).map(n=>[n,WKS.reduce((a,_,w)=>a+(cell(T.id,w,0)===n?1:0)+(cell(T.id,w,1)===n?1:0),0)]).sort((a,b)=>a[1]-b[1]);x.fix=cand[0]?{n:cand[0][0],cnt:cand[0][1]}:null});return f}
 const effNow=(t,s)=>cell(t,CURW,s);
 const PHONE={"Tom Becker":"303-555-0142","Nia Brooks":"303-555-0177","Priya Shah":"720-555-0119","Sam Patel":"303-555-0186","Jordan Lee":"720-555-0133","Dev Rao":"303-555-0158","Maya Ortiz":"720-555-0101","Avery Chen":"303-555-0164"};
 const ESC={sd:{sev:"P1 and P2",lv:[{w:"Primary on-call",wait:0,ch:["Push","SMS"]},{w:"Primary on-call",wait:5,ch:["Phone call"]},{w:"Secondary on-call",wait:10,ch:["Push","SMS","Phone call"]},{w:"Service owner",wait:15,ch:["Phone call"]},{w:"CIO office",wait:30,ch:["Phone call","Teams"]}]},
  pe:{sev:"P1 and P2",lv:[{w:"Primary on-call",wait:0,ch:["Push","SMS"]},{w:"Primary on-call",wait:5,ch:["Phone call"]},{w:"Secondary on-call",wait:10,ch:["Push","SMS","Phone call"]},{w:"Service owner",wait:15,ch:["Phone call"]}]},
  ds:{sev:"P1 only",lv:[{w:"Primary on-call",wait:0,ch:["Push","SMS"]},{w:"Secondary on-call",wait:10,ch:["Phone call"]},{w:"Lumen duty manager",wait:15,ch:["Phone call"]}]}};
 const ESCW=["Primary on-call","Secondary on-call","Team lead","Service owner","Lumen duty manager","CIO office"],ESCC=["Push","SMS","Phone call","Teams","Email"];
 const escName=(t,w)=>w==="Primary on-call"?effNow(t,0):w==="Secondary on-call"?effNow(t,1):w==="Team lead"?"Tom Becker":w==="Service owner"?"Maya Ortiz":w==="CIO office"?"CIO office":"Lumen duty desk";
 function shiftCell(T,w,s){const n=cell(T.id,w,s),p=n&&onPTO(n,w),dbl=s===0&&n&&OCT.some(o=>o.id!==T.id&&cell(o.id,w,0)===n),ov=OVR[`${T.id}|${w}|${s}`];
  return `<div class="svc-shift ${n?"":"open"} ${w===CURW?"now":""}" data-dnd="${T.id}|${w}|${s}" data-dnd-scope="svc_oc" aria-label="${T.n} ${slotN[s]} week of ${wkL(w)}">${n?`<div class="svc-pc ${p?"bad":dbl?"warn":""}" data-dnd-id="C:${T.id}|${w}|${s}" tabindex="0">${grip}${av(n)}<span class="svc-pn">${E(n.split(" ")[0])}</span>${p?`<em title="${E(p.note)}">PTO</em>`:dbl?`<em title="Primary on two teams">x2</em>`:ov?`<em title="${E(ov.why)}">swap</em>`:""}</div>`:`<span class="svc-open">Open shift</span>`}</div>`}
 function ocGrid(){return `<div class="svc-ocwrap"><div class="svc-oc" style="--n:${WKS.length}"><span></span>${WKS.map((_,i)=>`<b class="${i===CURW?"cur":""}">${wkL(i)}${i===CURW?"<small>this week</small>":""}</b>`).join("")}${OCT.map(T=>`<h4 style="--tc:${col(T.c)}">${E(T.n)}</h4>${[0,1].map(s=>`<span class="svc-rl">${slotN[s]}</span>${WKS.map((_,w)=>shiftCell(T,w,s)).join("")}`).join("")}`).join("")}</div></div>`}
 function ocPool(){return `<div class="svc-poolh"><b>People</b><span class="muted small">Drag a person onto a shift. Drag a shift onto another to swap, or back here to unassign.</span></div><div class="svc-pool" data-dnd="pool" data-dnd-scope="svc_oc" data-dnd-dir="x">${PEOPLE.map(p=>`<div class="svc-pc" data-dnd-id="P:${p[0]}" tabindex="0">${grip}${av(p[0])}<span class="svc-pn">${E(p[0])}</span><span class="muted small">${E(p[1])}</span></div>`).join("")}</div>`}
 DND.on("svc_oc",(id,from,to)=>{let src=id.startsWith("C:")?id.slice(2).split("|"):null,name=id.startsWith("P:")?id.slice(2):cell(src[0],+src[1],+src[2]);
  if(to==="pool"){if(src){setCell(src[0],+src[1],+src[2],null);toast(name+" removed from the rotation. That shift is now open.","warn");audit("unassigned on-call",name)}render();return}
  const [t,w,s]=to.split("|"),W=+w,Sl=+s,prev=cell(t,W,Sl),T=OCT.find(o=>o.id===t);
  if(src&&src[0]===t&&+src[1]===W&&+src[2]===Sl)return render();
  if(cell(t,W,1-Sl)===name&&!(src&&src[0]===t&&+src[1]===W)){toast(name+" cannot be both primary and secondary for "+T.n+" in the same week","warn");render();return}
  setCell(t,W,Sl,name);if(src)setCell(src[0],+src[1],+src[2],prev);
  const p=onPTO(name,W);toast(name+" assigned as "+slotN[Sl].toLowerCase()+", "+T.n+", week of "+wkL(W)+(prev&&src?". "+prev+" took the other shift.":"")+(p?". Heads up: "+p.note.toLowerCase()+".":""),p?"warn":"good");audit("assigned on-call",name+" → "+T.n+" "+slotN[Sl]+" "+wkL(W));render()});
 DND.on("svc_esc",(id,from,to,idx)=>{const L=ESC[V.escTeam].lv,i=+id.slice(2),[x]=L.splice(i,1);L.splice(Math.min(idx,L.length),0,x);L.forEach((l,k)=>{if(k===0)l.wait=0});toast("Level order updated. The first level always pages at once.","good");audit("reordered escalation",V.escTeam);render()});
 function escEditor(){const T=OCT.find(o=>o.id===V.escTeam),P=ESC[T.id];let cum=0;
  return `<div class="row svc-cats" role="group" aria-label="Team">${OCT.map(o=>`<button class="chip" data-svc="escteam|${o.id}" aria-pressed="${o.id===T.id}">${E(o.n)}</button>`).join("")}</div>
  <p class="muted small" data-role="story">Applies to ${P.sev} incidents for ${E(T.n)}. Each level starts after the wait time since the previous level if nobody has acknowledged. Drag levels to reorder.</p>
  <div class="svc-lvs" data-dnd="lv" data-dnd-scope="svc_esc">${P.lv.map((l,i)=>{cum+=l.wait;return `<div class="svc-lv glass" data-dnd-id="L:${i}" tabindex="0">${grip}<span class="svc-ln">${i+1}</span><div class="svc-lb"><b>${E(l.w)}</b> <span class="muted small">${E(escName(T.id,l.w))}</span><div class="row small"><span class="pill metric" data-role="metric">T+${cum} min</span>${ESCC.map(c=>`<button class="chip" data-nodrag data-svc="ech|${i}|${c}" aria-pressed="${l.ch.includes(c)}">${c}</button>`).join("")}</div></div><label class="svc-wait" data-nodrag><span class="small muted">Wait</span><input class="fin" type="number" min="0" max="120" data-svc-ew="${i}" value="${l.wait}" ${i===0?"disabled":""} aria-label="Minutes to wait before level ${i+1}"><span class="small muted">min</span></label><button class="btn quiet" data-nodrag data-svc="edel|${i}" aria-label="Remove level ${i+1}">Remove</button></div>`}).join("")}</div>
  <div class="row"><button class="btn" data-svc="eadd">Add a level</button><span class="formula small" style="font-size:14px">Time to last level = Σ wait times = ${cum} min. ${cum>45?"That is long for a P1; consider a shorter wait.":"Within the 45 minute P1 guideline."}</span></div>`}
 function ocNow(){return `<div class="grid g3">${OCT.map(T=>{const a=effNow(T.id,0),b=effNow(T.id,1),ov=OVR[`${T.id}|${CURW}|0`];return `<div class="card glass svc-now" style="--tc:${col(T.c)}"><div class="cardhead"><div><h3>${E(T.n)}</h3><span class="muted small">Hand-off Mon Oct 12 at 08:00 Mountain</span></div>${pill("On call now","good")}</div>${[[a,"Primary"],[b,"Secondary"]].map(([n,l])=>`<div class="svc-row">${n?who(n):who(null)}<span class="muted small">${l}</span><span class="small" style="margin-left:auto">${n?E(PHONE[n]||""):""}</span></div>`).join("")}${ov?`<p class="small muted">Override: ${E(ov.why)}. Originally ${E(ov.from)}.</p>`:""}<div class="row"><button class="btn" data-svc="page|${T.id}">Page primary</button></div></div>`}).join("")}</div>`}
 function ocSwaps(){return `<div class="row"><button class="btn primary" data-svc="override">Add an override</button><button class="btn" data-svc="swap">Request a swap</button></div>`+TBL(["Request","Shift","Hand over to","Reason","Status",""],SWAPS.map(s=>{const T=OCT.find(o=>o.id===s.team);return `<tr><td>${who(s.who)}</td><td>${E(T.n)} ${slotN[s.slot].toLowerCase()}<br><span class="muted small">week of ${wkL(s.wk)}</span></td><td>${who(s.to)}</td><td class="small">${E(s.msg)}</td><td>${pill(s.st,s.st==="Pending"?"warn":s.st==="Approved"?"good":"bad")}</td><td>${s.st==="Pending"?`<div class="row" style="flex-wrap:nowrap"><button class="btn" data-svc="swok|${s.id}">Approve</button><button class="btn quiet" data-svc="swno|${s.id}">Decline</button></div>`:""}</td></tr>`}))+`<div class="eyebrow" style="margin-top:6px">Active overrides</div>`+TBL(["Shift","Now covered by","Originally","Why"],Object.entries(OVR).map(([k,o])=>{const [t,w,s]=k.split("|"),T=OCT.find(x=>x.id===t);return `<tr><td>${E(T.n)} ${slotN[+s].toLowerCase()}, ${E(o.dates)}</td><td>${who(cell(t,+w,+s))}</td><td>${who(o.from)}</td><td class="small">${E(o.why)}</td></tr>`}))}
 REG("svc_oncall","On-call and escalation","service","M12 3a6 6 0 0 0-6 6c0 6-3 7-3 7h18s-3-1-3-7a6 6 0 0 0-6-6zM10 20a2 2 0 0 0 4 0",()=>{const gaps=detect(),total=OCT.length*WKS.length*2,cov=total-gaps.filter(g=>g.ty==="gap").length;
  const story=gaps.length?`${cov} of ${total} shifts in the next six weeks have a person, but <b>${gaps.length} need attention</b>: ${gaps.slice(0,2).map(g=>g.text.replace(/\.$/,"")).join("; ")}${gaps.length>2?`; and ${gaps.length-2} more`:""}. Fix them before the Lumen index rebuild window on Oct 22 to 23.`:`All ${total} shifts in the next six weeks are covered with no conflicts.`;
  return `<div class="screen">${hero("On-call and escalation","Who gets the page at 3 a.m.",`Right now <b>${E(effNow("sd",0))}</b> is primary for the Service desk, <b>${E(effNow("pe",0))}</b> for Platform and <b>${E(effNow("ds",0))}</b> for Data and search. ${story}`,`<div class="row"><button class="btn primary" data-svc="override">Add an override</button><button class="btn" data-svc="swap">Request a swap</button>${whyPop("On-call rotations are shown to team leads and service owners.")}</div>`)}${lensNote()}
  ${card("Who is on call now","Primary and secondary for each team, with the phone number the escalation policy will ring.",ocNow())}
  ${card("Coverage check",gaps.length?`${gaps.length} problem${gaps.length>1?"s":""} found by scanning every shift for gaps, time off, double bookings and fatigue.`:"Every shift is covered.",gaps.length?`<div class="svc-gaps">${gaps.map((g,i)=>`<div class="svc-gap ${g.sev}"><div>${pill(g.ty==="gap"?"Open shift":g.ty==="pto"?"Time off":g.ty==="dbl"?"Double booked":"Fatigue",g.sev)}<p>${E(g.text)}</p>${g.fix?`<span class="muted small">Claude suggests <b>${E(g.fix.n)}</b>: free that week, no time off, ${g.fix.cnt} shift${g.fix.cnt===1?"":"s"} in this window.</span>`:`<span class="muted small">No one on this team is free that week. Borrow from another team.</span>`}</div>${g.fix?`<button class="btn" data-svc="fix|${i}">Assign ${E(g.fix.n.split(" ")[0])}</button>`:""}</div>`).join("")}</div>`:`<p class="muted">Nothing to fix.</p>`,aiChip({model:"Claude Sonnet",conf:.86,title:"Coverage suggestions",note:"Suggests the free teammate with the fewest shifts. It never changes the schedule without your click.",src:["Rotation","Time off from Microsoft 365","Skills by team"]}))}
  ${card("Rotation calendar","Six weeks, three teams. This week is outlined. Drag people onto shifts.",ocPool()+ocGrid())}
  ${views("svc_ocv",["Escalation policy","Overrides and swaps"],[card("Escalation policy editor","Levels, waits and channels. Changes apply to the next page, never to one in flight.",escEditor()),card("Overrides and swap requests","One-off cover and shift hand-overs with approval.",ocSwaps())])}</div>`});
