 function matrixTable(){return TBL(["Event","Source","Severity","Who hears about it"].concat(CHN.map(c=>c[1])),EVT.map(e=>`<tr><td><b>${E(e.n)}</b></td><td>${E(e.src)}</td><td>${pill(e.sev,e.sev==="Urgent"?"bad":e.sev==="High"?"warn":e.sev==="Normal"?"info":"mute")}</td><td class="small">${E(e.to)}</td>${CHN.map(c=>`<td style="text-align:center">${tg(!!MX[e.id][c[0]],`mx|${e.id}|${c[0]}`,e.n+" on "+c[1])}</td>`).join("")}</tr>`),"svc-mx")}
 function personasPane(){const keys=Object.keys(PERSONAS);return TBL(["Persona","Digest","Delivered by","Include"],keys.map(k=>`<tr style="cursor:default"><td><b>${E(PERSONAS[k].n)}</b><br><span class="muted small">${E(PERSONAS[k].who)}</span></td>${["freq","ch","fl"].map(f=>`<td><select class="fin" data-svc-dg="${k}|${f}" aria-label="${E(PERSONAS[k].n)} ${f}">${DIGO[f].map(o=>`<option ${DIG[k]&&DIG[k][f]===o?"selected":""}>${o}</option>`).join("")}</select></td>`).join("")}</tr>`))}
 function quietPane(){return `<div class="svc-q"><label class="row"><span>Quiet hours</span>${tg(QH.on,"q|on","Quiet hours")}</label><label class="row"><span>From</span><input class="fin" type="time" data-svc-qt="from" value="${QH.from}" style="width:auto"></label><label class="row"><span>Until</span><input class="fin" type="time" data-svc-qt="to" value="${QH.to}" style="width:auto"></label><label class="row"><span>Time zone</span><select class="fin" data-svc-qt="tz" style="width:auto">${["Mountain","Eastern","Pacific","UTC"].map(z=>`<option ${QH.tz===z?"selected":""}>${z}</option>`).join("")}</select></label><label class="row"><span>All weekend</span>${tg(QH.wk,"q|wk","All weekend")}</label><label class="row"><span>Urgent events break through</span>${tg(QH.p1,"q|p1","Urgent break through")}</label></div><p class="muted" data-role="story">${QH.on?`Between <b>${QH.from}</b> and <b>${QH.to}</b> ${E(QH.tz)}${QH.wk?" and all weekend":""}, non-urgent messages wait for the morning digest. <b>${PIPE.quiet}</b> were held last night. ${QH.p1?"Urgent events such as a P1 page still arrive at once.":"Warning: urgent events will also wait, so a 3 a.m. P1 would not page anyone."}`:"Quiet hours are off, so every message arrives when it happens."}</p>`}
 function tplPane(){const t=TPL.find(x=>x.id===V.tplSel)||TPL[0];return `<div class="row"><button class="btn primary" data-svc="tplnew">New template</button></div><div class="svc-two">${TBL(["Event","Channel","Updated"],TPL.map(x=>`<tr data-svc="tplsel|${x.id}" ${x.id===t.id?'style="outline:2px solid var(--accent);outline-offset:-2px"':""}><td><b>${E(evN(x.ev))}</b></td><td>${E(chN(x.ch))}</td><td>${x.up}</td></tr>`))}<section class="card glass"><div class="cardhead"><div><h3>${E(evN(t.ev))} on ${E(chN(t.ch))}</h3><span class="muted small" data-role="story">Rendered with a sample ticket.</span></div></div><div class="svc-prevmsg ${t.ch}">${t.ch!=="sms"&&t.sub?`<b>${renderTpl(t.sub)}</b>`:""}<p>${renderTpl(t.body)}</p></div><div class="row" style="margin-top:12px"><button class="btn" data-svc="tpledit|${t.id}">Edit template</button></div></section></div>`}
 function logPane(){const f=V.logF,rows=LOG.filter(l=>f==="All"||l.st===f);return `<div class="row svc-cats">${["All","Delivered","Failed","Suppressed","Deferred"].map(s=>`<button class="chip" data-svc="logf|${s}" aria-pressed="${f===s}">${s} <span class="muted">${s==="All"?LOG.length:LOG.filter(l=>l.st===s).length}</span></button>`).join("")}</div>`+TBL(["Time","Event","Recipient","Channel","Result","Detail",""],rows.map(l=>`<tr data-svc="log|${l.id}"><td>${l.t}</td><td>${E(evN(l.ev))}</td><td>${who(l.who)}</td><td>${E(chN(l.ch))}</td><td>${pill(l.st,stCl3[l.st])}</td><td class="small">${E(l.why||"Accepted by provider")}</td><td>${l.st==="Failed"?`<button class="btn" data-svc="retry|${l.id}">Retry</button>`:""}</td></tr>`))}
 REG("svc_notify","Notification engine","automate","M12 3a6 6 0 0 0-6 6c0 6-3 7-3 7h18s-3-1-3-7a6 6 0 0 0-6-6zM10 20a2 2 0 0 0 4 0",()=>{syncMetrics();const fl=LOG.filter(l=>l.st==="Failed").length,rate=PIPE.ok/(PIPE.ok+PIPE.fail)*100;
  return `<div class="screen">${hero("Notification engine",`${rate.toFixed(1)}% delivered, ${fl} failures to fix`,`Of <b>${PIPE.ev.toLocaleString()}</b> events in 24 hours, <b>${PIPE.matched.toLocaleString()}</b> found a recipient, <b>${PIPE.sup+PIPE.thr}</b> were stopped as duplicates or throttled, and <b>${PIPE.quiet}</b> waited for the morning. <b>${fl}</b> recent failures need a person, mostly bad contact data rather than outages.`,`<div class="row">${fchip("m_notifdel")}<button class="btn primary" data-svc="tplnew">New template</button>${aiChip({model:"Claude Sonnet",conf:.83,title:"Failure triage",note:"Groups failures by provider answer and proposes a fallback channel. A person approves any contact-record change.",src:["Delivery log","Contact records"]})}</div>`)}${lensNote()}
  ${tiles([TL("Events in 24 h",PIPE.ev.toLocaleString(),"2,906 notified","good"),TL("Delivery rate",rate.toFixed(1)+"%","goal 98%",rate>=98?"good":rate>=93?"warn":"bad"),TL("Stopped as noise",PIPE.sup+PIPE.thr,"duplicates and throttling","good"),TL("Failed",PIPE.fail,fl+" in the log below",fl?"bad":"good")])}
  ${views("svc_ntv",["Pipeline","Channel matrix","Personas and quiet hours","Templates","Delivery log"],[card("How a notification travels","Select a stage to see its rules and today's numbers.",pipeVis()),card("Event by channel matrix","Switch a channel on or off for each event. SMS is limited to Urgent and High events to protect people's phones.",matrixTable()),card("Personas and quiet hours","Each persona chooses a digest rhythm, a channel and a severity floor. Quiet hours apply to everyone except Urgent events.",personasPane()+`<div class="eyebrow" style="margin-top:6px">Quiet hours</div>`+quietPane()),card("Templates","One template per event and channel, with variables and a live preview.",tplPane()),card("Delivery log","Every attempt with the provider's answer. Fix failures here.",logPane())])}</div>`});
 function logDrawer(id){const l=LOG.find(x=>x.id===id);if(!l)return;openDrawer(`<div class="eyebrow">Delivery ${l.id}</div><h3>${E(evN(l.ev))} to ${E(l.who)}</h3><div class="row" style="margin:6px 0 12px">${pill(l.st,stCl3[l.st])}${pill(chN(l.ch),"mute")}<span class="muted small">${l.t}</span></div><p class="muted" data-role="story">${E(l.why||"The provider accepted the message and confirmed delivery.")}</p><dl class="kv"><dt>Rule matched</dt><dd>${E(evN(l.ev))} → ${E((EVT.find(e=>e.id===l.ev)||{}).to||"")}</dd><dt>Dedupe key</dt><dd>${l.ev}:INC0004417:${slug(l.who)}</dd><dt>Template</dt><dd>${(TPL.find(t=>t.ev===l.ev&&t.ch===l.ch)||{id:"Default"}).id}</dd><dt>Attempts</dt><dd>${l.st==="Failed"?l.perm?"1 (permanent error, no retry)":"1 of 3, next retry in 10 minutes":"1"}</dd></dl>${l.st==="Failed"?`<div class="row"><button class="btn primary" data-svc="retry|${l.id}">Retry now</button>${l.ch!=="teams"?`<button class="btn" data-svc="fallback|${l.id}">Send on Teams instead</button>`:`<button class="btn" data-svc="fallback|${l.id}">Send by email instead</button>`}</div>`:""}`)}
 /* ================= Self-service portal and Virtual Agent ================= */
 const ROUTES={kb:["Answer from knowledge","info"],cat:["Catalog request","good"],inc:["Open an incident","bad"],hum:["Human handoff","warn"],ask:["Needs clarification","mute"]};
 const VA_KW={kb:[["how do i",.5],["how to",.5],["how can i",.5],["reset",.6],["password",.7],["mfa",.7],["multifactor",.7],["authenticator",.6],["vpn",.7],["phish",.8],["voicemail",.7],["forward",.4],["company portal",.6],["what is",.4],["where do",.4],["where can",.4],["policy",.4],["find a",.3],["standard laptop",.5],["book a room",.5]],
  cat:[["i need",.5],["need a",.55],["can i get",.6],["request",.5],["order",.6],["new laptop",.8],["laptop",.2],["install",.45],["access to",.6],["new hire",.8],["onboard",.6],["av support",.7],["conference room",.5],["recording",.3],["new report",.7],["power bi",.3],["visio",.3],["acrobat",.3],["shared mailbox",.7],["licence for",.4],["license for",.4]],
  inc:[["down",.6],["outage",.8],["not working",.75],["broken",.65],["can't",.35],["cannot",.35],["error",.5],["crash",.6],["slow",.5],["timeout",.6],["timing out",.7],["failed",.4],["frozen",.5],["urgent",.3],["blocked",.3],["stuck",.5],["keeps",.25]],
  hum:[["human",.9],["person",.7],["real person",.9],["someone",.5],["talk to",.8],["speak to",.8],["call me",.6],["help desk",.5],["representative",.8],["escalate",.85],["supervisor",.7]]};
 function vaScore(q){const l=" "+q.toLowerCase()+" ",sc={};Object.keys(VA_KW).forEach(r=>{let p=1;const hit=[];VA_KW[r].forEach(([k,w])=>{if(l.includes(k)){p*=1-w;hit.push(k)}});sc[r]={s:Math.round((1-p)*100)/100,hit}});return sc}
 const CATKW=[["laptop",/laptop|computer|notebook|macbook/],["software",/install|software|visio|acrobat|power bi|tableau|figma|licen[cs]e for/],["access_repo",/repository|contract.*access|access.*contract/],["newhire",/new hire|onboard|starting on|joins us/],["av",/\bav\b|conference|recording|livestream|projector|boardroom|standards hall/],["report",/report|dashboard/],["mailbox",/mailbox|distribution list|teams channel/]];
 const kbBest=q=>{const tk=q.toLowerCase().split(/\W+/).filter(w=>w.length>2&&!["how","the","and","can","for","get","you","with","need","what","does","are","where","into"].includes(w));let best=null,bs=0;KB.forEach(k=>{const hay=(k.t+" "+k.tags+" "+k.sum).toLowerCase();const s=tk.reduce((a,w)=>a+(hay.includes(w)?(k.tags.includes(w)?2:1):0),0);if(s>bs){bs=s;best=k}});return bs>=2?best:null};
 function vaPush(m){V.va.push(m);drawVA()}
 function vaTyping(then){V.va.push({ai:1,typing:1});drawVA();setTimeout(()=>{V.va=V.va.filter(m=>!m.typing);then();drawVA()},620)}
 function vaSend(q){q=String(q||"").trim();if(!q)return;V.va.push({me:1,t:q});audit("asked Virtual Agent",q);drawVA();const sc=vaScore(q);vaTyping(()=>vaReply(q,sc))}
 function vaReply(q,sc){const l=q.toLowerCase(),order=Object.keys(sc).sort((a,b)=>sc[b].s-sc[a].s);let r=order[0];const top=sc[r].s;
  if(sc.hum.s>=.7)r="hum";else if(sc.inc.s>=.6&&sc.inc.s>=sc.cat.s-.1&&sc.inc.s>=sc.kb.s)r="inc";
  if(top<.45&&r!=="hum"){V.vaMiss=(V.vaMiss||0)+1;return V.va.push({ai:1,route:"ask",sc,conf:top,why:"No route scored above 45%.",t:V.vaMiss>=2?"I still cannot tell what you need, and I would rather not guess. I can bring in a person who will see this whole chat.":"I am not sure what you need yet. Which of these is closest?",btn:V.vaMiss>=2?[["Talk to a person","vahand"]]:[["Answer a question","vachip|How do I reset my password?"],["Request something","vachip|I need a new laptop"],["Report a problem","vachip|Contract Repository search is timing out"],["Talk to a person","vahand"]]})}
  V.vaMiss=0;
  if(r==="kb"){const k=kbBest(q);if(!k)return vaReply(q,Object.assign({},sc,{kb:{s:0,hit:[]},cat:{s:.5,hit:["fallback"]}}));return V.va.push({ai:1,route:"kb",sc,conf:Math.max(.62,sc.kb.s*.97),why:"Question words and topic terms matched "+k.id+".",t:`<p>${E(k.sum)}</p><ol class="svc-fl">${k.steps.slice(0,3).map(s=>`<li><span>${E(s)}</span></li>`).join("")}</ol>`,cites:[k.id],kbid:k.id})}
  if(r==="cat"){const hit=CATKW.find(c=>c[1].test(l));const it=hit?ITEM(hit[0]):null;if(!it)return V.va.push({ai:1,route:"ask",sc,conf:top,why:"Catalog intent, but no item matched.",t:"That sounds like a request, but I cannot find a matching catalog item. Browse the catalog, or I can bring in a person.",btn:[["Browse the catalog","vacat"],["Talk to a person","vahand"]]});
   const pre=Object.assign({},defVals(it));if(it.id==="laptop"){if(/developer|dev\b|16/.test(l))pre.model="Developer 16-inch";if(/designer/.test(l))pre.model="Designer workstation";if(/replac|old|broken|end of life/.test(l))pre.reason="Replacement, end of life";else if(/new hire|starting/.test(l))pre.reason="New hire"}if(it.id==="software"){const m=Object.keys(SW_PRICE).find(t=>l.includes(t.toLowerCase().replace("microsoft ","")));if(m)pre.title=m}if(it.id==="av"&&/boardroom/.test(l))pre.room="Boardroom";
   const p=priceOf(it,pre),ap=apprFor(it,pre,PU),sd=SDI(it.sla);return V.va.push({ai:1,route:"cat",sc,conf:Math.max(.6,sc.cat.s*.95),why:"Request words matched the catalog item "+it.n+".",t:`<p>I can start <b>${E(it.n)}</b> for you. ${p?`It shows back <b>${money(p)}</b> to your department. `:"There is no charge. "}${ap.length?`${ap.map(a=>E(a.who)).join(" and ")} will be asked to approve. `:"No approval is needed. "}The target is ${clk(sd.tgt,sd.cal)}.</p><p class="muted small">I filled in what you told me. You review everything before it is sent.</p>`,btn:[["Open the request form","vareq|"+it.id+"|"+JSON.stringify(pre).replace(/\|/g,"/")],["See the item details","vaitem|"+it.id],["Not now","vanot"]],cites:[]})}
  if(r==="inc"){const dup=/search|repository|contract/.test(l);return V.va.push({ai:1,route:"inc",sc,conf:Math.max(.62,sc.inc.s*.95),why:"Failure words ("+sc.inc.hit.join(", ")+") suggest something is broken, not a question or a request.",t:dup?`<p>This sounds like a problem, and it may be a known one. <b>INC0004417</b> (Contract Repository search timing out, P2) is already open and Lumen is working on it. I can add you as an affected user so you get updates, or open a separate incident if yours is different.</p>`:`<p>That sounds like something is broken. I will draft an incident so you do not have to fill in the form: I need your impact and urgency, and I will work out the priority and the clock.</p>`,btn:dup?[["Add me to INC0004417","vafollow"],["Open a new incident","vainc|"+q.replace(/\|/g," ")]]:[["Open an incident","vainc|"+q.replace(/\|/g," ")],["Talk to a person","vahand"]],cites:[]})}
  if(r==="hum"){const n=V.hand.length;V.hand.unshift({id:"CHAT00"+(512+n),q,st:"Waiting, position 2",who:"Tom Becker",open:fdtS(NOW)});V.vaStats.ticketed++;syncMetrics();audit("escalated to a human","CHAT00"+(512+n));
   const prior=V.va.filter(m=>m.ai&&m.route&&m.route!=="ask"&&m.route!=="hum").slice(-1)[0];
   setTimeout(()=>{V.va.push({ai:1,route:"hum",human:1,sc:null,conf:1,why:"A person has taken over the conversation.",t:"<p>Hi Priya, Tom Becker from the service desk. I have the summary from the chat, so you do not need to repeat anything. Can you tell me which device you are on?</p>"});drawVA()},2600);
   return V.va.push({ai:1,route:"hum",sc,conf:Math.max(.7,sc.hum.s),why:"You asked for a person.",t:`<p>Connecting you to the <b>service desk</b>. Three agents are online, you are second in line, and the wait is about 4 minutes. I have passed along this summary so you do not repeat yourself:</p><ul class="svc-sumry"><li>Priya Shah (Project manager, Parker HQ) asked: “${E(q)}”</li><li>${prior?"Tried: "+E(ROUTES[prior.route][0])+(prior.kbid?" ("+prior.kbid+")":"")+", not enough":"No self-service answer was tried"}</li><li>No open incident of hers matches</li><li>Suggested priority: P3 (single user)</li></ul>`,btn:[["Open the handoff record","vahandrec|CHAT00"+(512+n)]]})}
  return V.va.push({ai:1,route:"ask",sc,conf:top,why:"No route was clear.",t:"I am not sure yet. Could you tell me a little more?"})}
 function vaMsg(m,i){if(m.me)return `<div class="msg me">${E(m.t)}</div>`;if(m.typing)return `<div class="msg ai svc-typing" aria-label="Typing"><i></i><i></i><i></i></div>`;
  const R=ROUTES[m.route]||["Greeting","mute"],open=V.vaOpen===i;
  return `<div class="msg ai svc-vamsg">${m.route?`<div class="row svc-rt"><span class="pill ${R[1]}" data-role="metric">Route: ${m.human?"Person (Tom Becker)":R[0]}</span>${m.sc?`<button class="chip" data-svc="vawhy|${i}" aria-expanded="${open}" style="padding:2px 10px;font-size:12px">${open?"Hide":"How I chose"}</button>`:""}</div>`:""}${m.route&&open&&m.sc?`<div class="svc-rs" data-role="story">${["kb","cat","inc","hum"].map(r=>`<div class="svc-rb"><span>${ROUTES[r][0]}</span><div class="svc-bar sm"><i class="${r===m.route?"good":"mute"}" style="width:${m.sc[r].s*100}%"></i></div><b class="num">${Math.round(m.sc[r].s*100)}%</b></div>`).join("")}<p class="muted small">${E(m.why)} Matched: ${m.sc[m.route]&&m.sc[m.route].hit.length?m.sc[m.route].hit.map(E).join(", "):"none"}.</p></div>`:""}<div class="svc-tx">${m.t}</div>${m.cites&&m.cites.length?`<div class="row small"><span class="muted">Sources:</span>${m.cites.map(c=>`<button class="chip" data-svc="kb|${c}" style="padding:2px 10px;font-size:12px">${c} ${E(KB.find(k=>k.id===c).t.slice(0,34))}…</button>`).join("")}</div>`:""}${m.btn?`<div class="row">${m.btn.map(b=>`<button class="btn ${b[1]==="vainc"||/^vareq|^vainc|^vafollow/.test(b[1])?"primary":""}" data-svc="${E(b[1])}">${E(b[0])}</button>`).join("")}</div>`:""}${m.kbid&&!m.fb?`<div class="row"><button class="btn" data-svc="vafb|ok|${i}">That solved it</button><button class="btn quiet" data-svc="vafb|no|${i}">Not quite</button></div>`:""}${m.route?`<div class="row small" style="margin-top:6px">${aiChip({model:m.human?"Service desk":"Claude Haiku",conf:m.conf,title:"How this reply was routed",note:m.why,src:m.cites&&m.cites.length?m.cites:["Routing rules","Your open requests"],guards:["Cannot submit anything without your confirmation","Cannot see other people's tickets"]})}</div>`:""}</div>`}
 function vaHTML(){return `<div class="svc-vamsgs" data-svc-vamsgs aria-live="polite">${V.va.map(vaMsg).join("")}</div>`}
 function drawVA(){const b=document.querySelector("[data-svc-vamsgs]");if(!b)return;b.outerHTML=vaHTML();const n=document.querySelector("[data-svc-vamsgs]");if(n)n.scrollTop=n.scrollHeight}
 if(!V.va.length)V.va.push({ai:1,t:"<p>Hi Priya. I can answer questions from our knowledge base, start a catalog request, open an incident, or bring in a person. Every reply shows which of those I chose and why.</p>"});
 const VAQ=["How do I reset my password?","I need a new laptop","Contract Repository search is timing out","Talk to a person"];
 function vaPanel(){return `<section class="card glass svc-va"><div class="cardhead"><div><h3>Virtual Agent</h3><span class="muted small" data-role="story">Four routes: answer, request, incident, person.</span></div>${fchip("m_deflect","Deflection")}</div><div class="row svc-legend">${["kb","cat","inc","hum"].map(r=>`<span class="pill ${ROUTES[r][1]}">${ROUTES[r][0]}</span>`).join("")}</div>${vaHTML()}<div class="row svc-qr">${VAQ.map(q=>`<button class="chip" data-svc="vachip|${E(q)}">${E(q)}</button>`).join("")}</div><form class="svc-vain" data-svc-vaform><input class="txtin" name="q" autocomplete="off" placeholder="Ask or describe what you need" aria-label="Message to the Virtual Agent"><button class="btn primary" type="submit">Send</button></form></section>`}
 function incForm(q){const fid="svc_inc";svcOpen({id:fid,title:"Open an incident",story:"Tell us what is broken and who is affected. We work out the priority from impact and urgency, start the right SLA clock and page whoever is on call for urgent ones.",submit:"Open incident",
  fields:[{section:"What happened"},{k:"t",label:"Short description",type:"text",req:true,ai:{label:"Tidy up",fn:v=>(v.t||"Problem").replace(/^./,c=>c.toUpperCase()).replace(/\.$/,"")}},{k:"svc",label:"What is affected",type:"select",opts:["Contract Repository","Standards Platform","Microsoft 365","Network and Wi-Fi","Lease subledger","Something else"],req:true,ph:"Choose one"},{k:"d",label:"Details",type:"longtext",wide:true,help:"What you were doing, any error text, when it started."},{section:"How bad is it"},{k:"imp",label:"Who is affected",type:"chips",opts:[["1","Many people"],["2","My team"],["3","Just me"]],req:true},{k:"urg",label:"Can you work around it",type:"chips",opts:[["1","No, I am blocked"],["2","Partly"],["3","Yes"]],req:true},{k:"doc",label:"Attach a screenshot",type:"file"}],
  defaults:{t:(q||"").slice(0,120),imp:"3",urg:"2"},
  live:(v,f)=>{const sum=(+v.imp||3)+(+v.urg||3),p=sum<=2?1:sum===3?2:sum===4?3:4,sd=SDI(p===1?"SLA-INC-P1":p===2?"SLA-INC-P2":"SLA-INC-P3"),due=addWork(NOW,sd.tgt,sd.cal),dup=/search|repository|contract/i.test(v.t||"")||v.svc==="Contract Repository";
   liveBox(f,`<div class="eyebrow">Priority and clock</div><div class="row"><span class="pill ${p<=2?"bad":p===3?"warn":"info"}" data-role="metric">P${p}</span><span class="pill mute">${E(sd.id)}: ${clk(sd.tgt,sd.cal)}</span><span class="pill info">Due ${fdt(due)}</span>${p<=2?`<span class="pill warn">Pages ${E(effNow("sd",0))} (Service desk on-call)</span>`:""}</div><div class="formula small" style="font-size:14px;margin-top:8px">Priority = impact + urgency (1 is worst): sum 2 = P1, 3 = P2, 4 = P3, 5 or more = P4. Yours: ${v.imp||3} + ${v.urg||3} = ${sum}, so P${p}.</div>${dup?`<p class="pill warn" style="margin-top:8px">A similar incident is open: INC0004417 (Lumen). You can follow it instead from the chat.</p>`:""}`)},
  onSubmit:v=>{const sum=(+v.imp)+(+v.urg),p=sum<=2?1:sum===3?2:sum===4?3:4,id="INC00044"+(24+V.myInc.length);V.myInc.unshift({id,t:v.t,pri:p,st:"New",open:fdtS(NOW),due:fdt(addWork(NOW,SDI(p===1?"SLA-INC-P1":p===2?"SLA-INC-P2":"SLA-INC-P3").tgt,p===1?"24x7":"biz"))});V.vaStats.ticketed++;syncMetrics();V.va.push({ai:1,route:"inc",human:0,sc:null,conf:1,why:"Incident created from the form.",t:`<p><b>${id}</b> is open as P${p}. ${p<=2?E(effNow("sd",0))+" is being paged. ":""}You will get updates in Teams.</p>`});render();return {toast:id+" opened as P"+p,audit:id}}})}
 const NEWS=[{t:"Teams phone maintenance, Saturday Oct 10, 18:00 to 20:00 Mountain",s:"Calls may drop for up to 10 minutes. No action needed.",c:"info"},{t:"Contract Repository search is slow",s:"Lumen is working on it (INC0004417). Saved Favorites still open quickly.",c:"warn"}];
 function psearch(q){q=q.trim().toLowerCase();const box=document.querySelector("[data-svc-psr]");if(!box)return;if(!q){box.innerHTML="";return}const tk=q.split(/\s+/);const hits=[].concat(CAT.filter(c=>tk.every(t=>(c.n+" "+c.short+" "+c.cat).toLowerCase().includes(t))).map(c=>`<button class="svc-hit" data-svc="reqform|${c.id}">${IC(c.ic)}<span><b>${E(c.n)}</b><small class="muted">Catalog item · ${priceOf(c,defVals(c))?"from "+money(priceOf(c,defVals(c))):"no charge"}</small></span><span class="pill good">Request</span></button>`),KB.filter(k=>tk.every(t=>(k.t+" "+k.tags+" "+k.sum).toLowerCase().includes(t))).map(k=>`<button class="svc-hit" data-svc="kb|${k.id}">${ico("book")}<span><b>${E(k.t)}</b><small class="muted">Knowledge · ${k.id} · ${k.up}% found it helpful</small></span><span class="pill info">Read</span></button>`)).slice(0,6);
  box.innerHTML=hits.length?hits.join(""):`<div class="emptystate"><b>Nothing matches “${E(q)}”</b><span class="muted">Ask the Virtual Agent and it will route you.</span><button class="btn" data-svc="vachip|${E(q)}">Ask the Virtual Agent</button></div>`}
 function myOpen(){const mine=REQS.filter(r=>r.by===PU);const rows=mine.map(r=>{const c=ritmClock(r);return `<tr data-svc="req|${r.id}"><td><b>${E(itemOf(r).n)}</b><br><span class="muted small">${r.id}</span></td><td>${r.rej?pill("Rejected","bad"):pill(r.st,stCls2[r.st])}</td><td>${c.done?"Done "+fd(r.done):"Due "+fdt(c.due)}</td></tr>`}).concat(V.myInc.map(i=>`<tr style="cursor:default"><td><b>${E(i.t)}</b><br><span class="muted small">${i.id} · P${i.pri}</span></td><td>${pill(i.st,"bad")}</td><td>Due ${i.due}</td></tr>`),V.hand.map(h=>`<tr data-svc="vahandrec|${h.id}"><td><b>Chat with the service desk</b><br><span class="muted small">${h.id}</span></td><td>${pill("Chat","warn")}</td><td>${E(h.st)}</td></tr>`));return TBL(["What","Status","When"],rows,"svc-mine")}
 REG("svc_portal","Self-service portal","service","M3 11l9-8 9 8v9a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1zM9 21v-7h6v7",()=>{syncMetrics();const my=REQS.filter(r=>r.by===PU&&r.st!=="Delivered"),pa=my.filter(r=>r.st==="Awaiting approval"),st=V.vaStats,n=st.resolved+st.ticketed,pop=CAT.slice().sort((a,b)=>b.pop-a.pop).slice(0,6);
  return `<div class="screen">${hero("Self-service portal","Good morning, Priya. What do you need?",`This is the portal as Priya Shah sees it. She has <b>${my.length} open requests</b>${pa.length?`, and <b>${pa.length}</b> is waiting on an approval`:""}. Across the foundation, self-service handled <b>${Math.round(st.resolved/n*100)}%</b> of ${n.toLocaleString()} questions this month without a ticket; the Virtual Agent on the right shows how.`,`<div class="row">${fchip("m_deflect")}<button class="btn" data-svc="inc0">Report a problem</button><button class="btn" data-svc="gocat">Browse the catalog</button>${whyPop("This page is how employees see Oukala. Executives and service leads see it to judge the experience.")}</div>`)}${lensNote()}
  <div class="svc-pgrid"><div class="svc-pcol">
   <div class="svc-news glass">${NEWS.map(n=>`<div><span class="pill ${n.c}">${n.c==="warn"?"Known issue":"Heads up"}</span><b>${E(n.t)}</b><span class="muted small">${E(n.s)}</span></div>`).join("")}</div>
   ${card("Search","Looks through catalog items and knowledge articles at the same time.",`<div class="svc-search"><span class="svc-sico">${ico("search")}</span><input class="txtin" data-svc-ps placeholder="Try: new laptop, vpn, phishing, contract access" aria-label="Search the portal" autocomplete="off"></div><div class="svc-hits" data-svc-psr></div>`)}
   ${card("Popular requests","The six most ordered items in the last 90 days.",`<div class="svc-pop">${pop.map(it=>`<button class="svc-tile glass" data-svc="reqform|${it.id}"><span class="svc-ic">${IC(it.ic)}</span><b>${E(it.n)}</b><span class="muted small">${it.pop} ordered</span></button>`).join("")}</div>`)}
   ${card("My open requests","Everything you asked for, with its due date. Select one for the timeline.",myOpen())}
   ${card("Suggested for you","Because you opened a laptop request and a report request.",`<div class="svc-kbl">${["KB0122","KB0143","KB0156","KB0138"].map(id=>{const k=KB.find(x=>x.id===id);return `<button class="svc-hit" data-svc="kb|${id}">${ico("book")}<span><b>${E(k.t)}</b><small class="muted">${k.id} · ${k.views.toLocaleString()} views · ${k.up}% helpful</small></span></button>`}).join("")}</div>`,aiChip({model:"Claude Sonnet",conf:.81,title:"Why these articles",note:"Picked from your open requests and what similar people read first.",src:["Your requests","Article views"]}))}
  </div><aside>${vaPanel()}</aside></div></div>`});
 function kbDrawer(id){const k=KB.find(x=>x.id===id);if(!k)return;openDrawer(`<div class="eyebrow">Knowledge · ${k.id}</div><h3>${E(k.t)}</h3><div class="row" style="margin:6px 0 12px"><span class="pill info" data-role="metric">${k.views.toLocaleString()} views</span><span class="pill good" data-role="metric">${k.up}% found it helpful</span></div><p data-role="story">${E(k.sum)}</p><ol class="svc-fl">${k.steps.map(s=>`<li><span>${E(s)}</span></li>`).join("")}</ol><div class="row"><button class="btn" data-svc="kbyes|${k.id}">This helped</button><button class="btn quiet" data-svc="vachip|${E(k.t)}">Still stuck? Ask the Virtual Agent</button></div>`)}
 /* ================= forms: pick, override, swap, escalation level ================= */
 function pickForm(){svcOpen({id:"svc_pick",title:"Submit a request",story:"Choose what you need. The next form is built from that catalog item's questions, so you only answer what applies.",submit:"Continue",fields:[{k:"item",label:"What do you need?",type:"select",opts:CAT.map(c=>[c.id,c.n+" ("+c.cat+")"]),req:true,ph:"Choose a catalog item"}],defaults:{},onSubmit:v=>{setTimeout(()=>requestForm(v.item),0);return {toast:"Opening the request form",close:false}}})}
 function ocForm(){svcOpen({id:"svc_oc_override",title:"Add an on-call override",story:"An override puts someone else on a shift for a short time without rewriting the rotation. Escalation policies follow the override immediately, and both people are notified.",submit:"Apply override",
  fields:[{k:"t",label:"Team",type:"select",opts:OCT.map(o=>[o.id,o.n]),req:true},{k:"w",label:"Week",type:"select",opts:WKS.map((_,i)=>[String(i),"Week of "+wkL(i)]),req:true},{k:"s",label:"Shift",type:"chips",opts:[["0","Primary"],["1","Secondary"]],req:true},{k:"p",label:"Covered by",type:"people",req:true},{k:"dates",label:"Which days",type:"text",ph:"Wed Oct 7, 18:00 to 08:00",req:true},{k:"why",label:"Reason",type:"longtext",req:true,wide:true},{k:"n",label:"Tell both people",type:"toggle"}],
  defaults:{t:"sd",w:"1",s:"0",n:true},live:(v,f)=>{const T=OCT.find(o=>o.id===v.t),cur=T&&cell(T.id,+v.w,+v.s),pto=v.p&&onPTO(v.p,+v.w),dbl=v.p&&v.s==="0"&&OCT.some(o=>o.id!==v.t&&cell(o.id,+v.w,0)===v.p);liveBox(f,`<div class="eyebrow">What changes</div><p class="muted small" data-role="story">${cur?E(cur):"Nobody"} is currently ${slotN[+v.s||0].toLowerCase()} for ${E(T?T.n:"")}. ${v.p?E(v.p)+" takes over."+(pto?` <b>Warning: ${E(pto.note.toLowerCase())}.</b>`:"")+(dbl?" <b>Warning: already primary on another team that week.</b>":""):"Choose who covers."}</p>`)},
  onSubmit:v=>{const k=`${v.t}|${+v.w}|${+v.s}`,prev=cell(v.t,+v.w,+v.s);OVR[k]={from:prev||"Open shift",why:v.why,dates:v.dates};setCell(v.t,+v.w,+v.s,v.p);render();return {toast:v.p+" now covers. Escalation policy updated.",audit:k}}})}
 function swapForm(){const opts=[];OCT.forEach(T=>WKS.forEach((_,w)=>[0,1].forEach(s=>{const n=cell(T.id,w,s);if(n&&w>=CURW)opts.push([`${T.id}|${w}|${s}`,`${n}: ${T.n} ${slotN[s].toLowerCase()}, ${wkL(w)}`])})));
  svcOpen({id:"svc_oc_swap",title:"Request a shift swap",story:"A swap hands your shift to a teammate. The team lead approves, and the rotation changes only after that.",submit:"Send request",fields:[{k:"shift",label:"Shift to hand over",type:"select",opts:opts,req:true,ph:"Choose a shift"},{k:"to",label:"Hand over to",type:"people",req:true},{k:"msg",label:"Message",type:"longtext",wide:true,ph:"Why, and anything they should know"}],defaults:{},
  onSubmit:v=>{const [t,w,s]=v.shift.split("|"),cur=cell(t,+w,+s);SWAPS.unshift({id:"SW"+(SWAPS.length+1),who:cur,team:t,wk:+w,slot:+s,to:v.to,msg:v.msg||"No message",st:"Pending"});render();return {toast:"Swap request sent to the team lead",audit:v.shift}}})}
 function escAddForm(){svcOpen({id:"svc_esc_lvl",title:"Add an escalation level",story:"A level pages someone if the previous level did not acknowledge within the wait time. Pick channels that cannot be ignored for urgent events.",submit:"Add level",fields:[{k:"w",label:"Who gets paged",type:"select",opts:ESCW,req:true},{k:"wait",label:"Wait after the previous level",type:"range",min:0,max:60,step:5,unit:" min"},{k:"ch",label:"Channels",type:"multi",opts:ESCC,req:true}],defaults:{w:"Team lead",wait:10,ch:["Phone call"]},
  live:(v,f)=>{const tot=ESC[V.escTeam].lv.reduce((a,l)=>a+l.wait,0)+(+v.wait||0);liveBox(f,`<p class="muted small" data-role="story">The new level would be reached ${tot} minutes after the first page. Policy guideline for P1 is 45 minutes or less.</p>`)},
  onSubmit:v=>{ESC[V.escTeam].lv.push({w:v.w,wait:+v.wait||0,ch:v.ch});render();return {toast:"Level added",audit:v.w}}})}
 /* ================= events ================= */
 const openFirst=(id,sc)=>{V.catSel=id;V.pv[id]=V.pv[id]||defVals(ITEM(id))};
 const scopeIt=sc=>sc==="cat"?ITEM(V.catSel):(PV.dz&&PV.dz.it);
 const scopeVals=sc=>sc==="cat"?V.pv[V.catSel]:V.dpv;
 document.addEventListener("click",e=>{const t=e.target.closest("[data-svc]");if(!t)return;const a=t.dataset.svc.split("|"),c=a[0];
  switch(c){
   case"item":openFirst(a[1]);go("svc_cat");break;
   case"cat":if(a[1]==="back"){V.catSel=null}else{V.catCat=a[1];V.catSel=null}render();break;
   case"gocat":V.catSel=null;go("svc_cat");break;
   case"design":itemDesigner(a[1]);break;
   case"pick":pickForm();break;
   case"order":{const vals=Object.assign({},V.pv[a[1]],{_for:PU});requestForm(a[1],vals);break}
   case"reqform":requestForm(a[1]);break;
   case"pvreset":delete V.pv[a[1]];V.pv[a[1]]=defVals(ITEM(a[1]));refreshPV("cat");break;
   case"vc":{const v=scopeVals(a[1]);if(!v)break;v[a[2]]=v[a[2]]===a[3]?"":a[3];refreshPV(a[1]);break}
   case"vm":{const v=scopeVals(a[1]);if(!v)break;const x=v[a[2]]||[];v[a[2]]=x.includes(a[3])?x.filter(y=>y!==a[3]):x.concat(a[3]);refreshPV(a[1]);break}
   case"vt":{const v=scopeVals(a[1]);if(!v)break;v[a[2]]=!v[a[2]];refreshPV(a[1]);break}
   case"req":openReqDrawer(a[1]);break;
   case"appr":decide(a[1],+a[2],a[3]==="ok");break;
   case"task":{const r=REQS.find(x=>x.id===a[1]),k=r.tasks[+a[2]],nx={Open:"In progress","In progress":"Done",Done:"Open"}[k.st];k.st=nx;r.tl.push([fdtS(NOW),`${k.t}: ${nx}`]);audit("task state",k.t+" → "+nx);if(r.tasks.every(x=>x.st==="Done"))toast("All tasks done. You can move the item to Delivered.","info");render();openReqDrawer(r.id);break}
   case"adv":{const r=REQS.find(x=>x.id===a[1]);moveReq(r.id,STAGES[STAGES.indexOf(r.st)+1]);render();openReqDrawer(r.id);break}
   case"nudge":{const r=REQS.find(x=>x.id===a[1]);const who_=r.st==="Awaiting approval"?(r.appr.find(x=>x.st==="Pending")||{who:"approver"}).who:"task owners";r.tl.push([fdtS(NOW),"Reminder sent to "+who_]);audit("nudged",r.id);toast("Reminder sent to "+who_,"info");openReqDrawer(r.id);break}
   case"slad":slaDrawer(a[1]);break;
   case"slaedit":slaForm(a[1]);break;
   case"slanew":slaForm();break;
   case"fc":fcDrawer(a[1]);break;
   case"swarm":{const k=TICKS.find(x=>x.id===a[1]);if(k){const h=effNow("sd",0)===k.own?effNow("sd",1):effNow("sd",0);k.rem=Math.max(.5,k.rem-1.5);k.note+=" "+h+" swarmed to help.";toast(h+" joined "+k.id+". Remaining work estimate down 1.5 h.","good");audit("swarmed",k.id+" + "+h);render();closeDrawer()}break}
   case"claim":V.claimed.lumen=true;toast("Credit claim drafted from vendor tickets LUM-87710 and LUM-87952 and sent for signature","good");audit("credit claim","Lumen");render();break;
   case"escteam":V.escTeam=a[1];render();break;
   case"ech":{const l=ESC[V.escTeam].lv[+a[1]];l.ch=l.ch.includes(a[2])?l.ch.filter(x=>x!==a[2]):l.ch.concat(a[2]);if(!l.ch.length){l.ch=[a[2]];toast("A level needs at least one channel","warn")}audit("escalation channel",a[2]);render();break}
   case"edel":{const L=ESC[V.escTeam].lv;if(L.length<2){toast("A policy needs at least one level","warn");break}L.splice(+a[1],1);L[0].wait=0;audit("removed escalation level",V.escTeam);toast("Level removed","good");render();break}
   case"eadd":escAddForm();break;
   case"page":{const T=OCT.find(o=>o.id===a[1]);toast("Paging "+effNow(T.id,0)+" by push and SMS. Level 2 rings in 5 minutes if there is no answer.","info");audit("paged",effNow(T.id,0));break}
   case"override":ocForm();break;
   case"swap":swapForm();break;
   case"swok":{const s=SWAPS.find(x=>x.id===a[1]);s.st="Approved";setCell(s.team,s.wk,s.slot,s.to);toast(s.to+" now holds the shift. Both people notified.","good");audit("swap approved",s.id);render();break}
   case"swno":{const s=SWAPS.find(x=>x.id===a[1]);s.st="Declined";toast("Swap declined","warn");audit("swap declined",s.id);render();break}
   case"fix":{const g=detect()[+a[1]];if(g&&g.fix){setCell(g.t,g.w,g.s,g.fix.n);toast(g.fix.n+" assigned. Gap closed.","good");audit("closed coverage gap",g.fix.n+" "+g.t+" "+wkL(g.w));render()}break}
   case"lic":licDrawer(a[1]);break;
   case"ast":astDrawer(a[1]);break;
   case"astret":{const x=HW.find(h=>h.id===a[1]);x.st="Retiring";toast(x.id+" marked for retirement","good");audit("asset retiring",x.id);closeDrawer();render();break}
   case"astrep":{const x=HW.find(h=>h.id===a[1]);x.st="In repair";toast(x.id+" sent to repair","info");audit("asset repair",x.id);closeDrawer();render();break}
   case"reclaim":reclaimForm();break;
   case"assetadd":assetForm();break;
   case"mx":{const ev=EVT.find(x=>x.id===a[1]),on=MX[a[1]][a[2]];if(a[2]==="sms"&&!on&&(ev.sev==="Info"||ev.sev==="Normal")){toast("SMS is limited to Urgent and High events so people keep trusting it","warn");break}MX[a[1]][a[2]]=on?0:1;if(!Object.values(MX[a[1]]).some(Boolean))toast(ev.n+" now has no channel, so nobody will hear about it","warn");audit("channel matrix",ev.n+" · "+a[2]+" "+(on?"off":"on"));render();break}
   case"pst":{const s=PST[+a[1]];openDrawer(`<div class="eyebrow">Pipeline stage ${+a[1]+1} of 6</div><h3>${s[0]}: ${s[1]}</h3><p class="muted" data-role="story">${s[2]}</p><ul class="steps">${s[3]().map(x=>`<li>${E(x)}</li>`).join("")}</ul><div class="row"><button class="btn quiet" data-svc="pstnext|${+a[1]}">${+a[1]<5?"Next stage":"Open delivery log"}</button></div>`);break}
   case"pstnext":if(+a[1]<5)t.dataset.svc="pst|"+(+a[1]+1),t.click();else{S.v.svc_ntv=4;closeDrawer();render()}break;
   case"q":QH[a[1]]=!QH[a[1]];audit("quiet hours",a[1]+" "+QH[a[1]]);render();break;
   case"tplnew":tplForm();break;
   case"tpledit":tplForm(a[1]);break;
   case"tplsel":V.tplSel=a[1];render();break;
   case"logf":V.logF=a[1];render();break;
   case"log":logDrawer(a[1]);break;
   case"retry":{const l=LOG.find(x=>x.id===a[1]);if(l.perm){toast("Still failing: "+l.why.split(".")[0]+". Use a fallback channel.","bad");break}l.st="Delivered";l.why="";PIPE.fail--;PIPE.ok++;syncMetrics();toast("Retry succeeded on "+chN(l.ch),"good");audit("retried notification",l.id);closeDrawer();render();break}
   case"fallback":{const l=LOG.find(x=>x.id===a[1]),fb=l.ch==="teams"?"email":"teams";l.ch=fb;l.st="Delivered";l.why="";PIPE.fail--;PIPE.ok++;syncMetrics();toast("Delivered on "+chN(fb)+" instead. A data-quality task was opened for "+l.who+"'s contact record.","good");audit("fallback channel",l.id+" → "+fb);closeDrawer();render();break}
   case"kb":kbDrawer(a[1]);break;
   case"kbyes":{const k=KB.find(x=>x.id===a[1]);toast("Thanks. That feeds the article's helpfulness score.","good");audit("article helpful",k.id);break}
   case"inc0":incForm("");break;
   case"vachip":{const q=a.slice(1).join("|");closeDrawer();if(S.screen!=="svc_portal"){go("svc_portal");setTimeout(()=>vaSend(q),300)}else vaSend(q);break}
   case"vareq":{const pre=JSON.parse(a.slice(2).join("|")||"{}");requestForm(a[1],Object.assign({_for:PU},pre),id=>{V.vaStats.ticketed++;syncMetrics();V.va.push({ai:1,route:"cat",human:0,sc:null,conf:1,why:"Request submitted from the form.",t:`<p>Done. <b>${id}</b> is submitted. ${REQS.find(r=>r.id===id).appr.length?E(REQS.find(r=>r.id===id).appr.filter(x=>x.st==="Pending")[0].who)+" has been asked to approve. ":""}You can follow it under My open requests.</p>`});drawVA()});break}
   case"vaitem":openFirst(a[1]);go("svc_cat");break;
   case"vacat":V.catSel=null;go("svc_cat");break;
   case"vanot":V.va.push({me:1,t:"Not now"});vaTyping(()=>V.va.push({ai:1,t:"<p>No problem. I will be here if you change your mind.</p>"}));break;
   case"vainc":incForm(a.slice(1).join("|"));break;
   case"vafollow":V.myInc.unshift({id:"INC0004417",t:"Contract Repository search timing out (following)",pri:2,st:"Following",open:fdtS(NOW),due:"Tue 17:00"});V.vaStats.resolved++;syncMetrics();audit("followed incident","INC0004417");V.va.push({ai:1,route:"inc",sc:null,conf:1,why:"Linked to a known incident.",t:"<p>Done. You are now an affected user on <b>INC0004417</b>. Sam Patel will update you, and no duplicate ticket was created.</p>"});drawVA();toast("You will get updates on INC0004417","good");break;
   case"vahand":vaSend("Talk to a person");break;
   case"vahandrec":{const h=V.hand.find(x=>x.id===a[1]);if(h)openDrawer(`<div class="eyebrow">Handoff ${h.id}</div><h3>Chat with the service desk</h3><div class="row" style="margin:6px 0 12px">${pill(h.st,"warn")}${who(h.who)}</div><p class="muted" data-role="story">The summary below was written by the Virtual Agent and attached so Priya does not repeat herself.</p><ul class="svc-sumry"><li>First message: “${E(h.q)}”</li><li>Priya Shah, Project manager, Parker HQ, Windows laptop MSF-10231</li><li>Open requests: RITM0010441 (laptop), RITM0010437 (report)</li><li>Suggested priority: P3</li></ul>${aiChip({model:"Claude Haiku",conf:.9,title:"Handoff summary",note:"Summarizes the chat for the agent. The agent decides what to do.",src:["This chat","Priya's open requests"]})}`);break}
   case"vafb":{const m=V.va[+a[2]];m.fb=a[1];if(a[1]==="ok"){V.vaStats.resolved++;syncMetrics();audit("deflected",m.kbid);V.va.push({ai:1,t:"<p>Glad that helped. I counted it as solved without a ticket.</p>"});toast("Counted as self-service: deflection is now "+METRICS.m_deflect.cur+"%","good")}else{V.va.push({ai:1,t:"<p>Sorry about that. Would you like me to raise a request or incident, or bring in a person?</p>",btn:[["Report a problem","vainc|"+(V.va.filter(x=>x.me).slice(-1)[0]||{t:""}).t],["Talk to a person","vahand"]]})}drawVA();break}
   case"vawhy":V.vaOpen=V.vaOpen===+a[1]?null:+a[1];drawVA();break;
  }});
 document.addEventListener("change",e=>{const t=e.target;
  if(t.dataset&&t.dataset.svcV){const [sc,k]=t.dataset.svcV.split("|"),v=scopeVals(sc);if(v){v[k]=t.type==="number"&&t.value!==""?+t.value:t.value;refreshPV(sc)}return}
  if(t.dataset&&t.dataset.svcDg){const [p,f]=t.dataset.svcDg.split("|");DIG[p][f]=t.value;audit("digest preference",PERSONAS[p].n+" · "+f+" = "+t.value);toast(PERSONAS[p].n+": "+t.value,"good");return}
  if(t.dataset&&t.dataset.svcQt){QH[t.dataset.svcQt]=t.value;audit("quiet hours",t.dataset.svcQt+" = "+t.value);render();return}
  if(t.dataset&&t.dataset.svcEw!==undefined){const l=ESC[V.escTeam].lv[+t.dataset.svcEw];l.wait=Math.max(0,Math.min(120,+t.value||0));audit("escalation wait",t.value+" min");render();return}
  const f=t.closest&&t.closest("[data-form^='svc_']");if(f){const sp=FORMSPEC[f.dataset.form];if(sp&&sp.live)sp.live(formValues(sp.id),sp.id)}});
 document.addEventListener("click",e=>{const f=e.target.closest&&e.target.closest("[data-form^='svc_']");if(f&&e.target.closest("[data-fmulti],[data-fai]")){const sp=FORMSPEC[f.dataset.form];if(sp&&sp.live)setTimeout(()=>sp.live(formValues(sp.id),sp.id),0)}});
 document.addEventListener("input",e=>{const t=e.target;if(t.dataset&&t.dataset.svcPs!==undefined)psearch(t.value);else if(t.dataset&&t.dataset.svcReqq!==undefined){V.reqQ=t.value;const p=t.selectionStart;render();const n=document.querySelector("[data-svc-reqq]");if(n){n.focus();n.setSelectionRange(p,p)}}});
 document.addEventListener("submit",e=>{const f=e.target.closest("[data-svc-vaform]");if(!f)return;e.preventDefault();const i=f.querySelector("input"),q=i.value;i.value="";vaSend(q)});
 /* ================= chat and search hooks ================= */
 ASKX.push(q=>{
  if(/(laptop).{0,30}(need|want|request|order|new)|(need|want|order|request|get).{0,25}laptop/i.test(q)){go("svc_cat");const m=/developer/i.test(q)?{model:"Developer 16-inch"}:{};say(q,{t:"Opening the <b>New laptop</b> request for you. A standard laptop shows back $1,840, needs Maya Ortiz to approve, and is due in about 5 business days. I filled what I could; you confirm before it is sent.",steps:["Matched the catalog item New laptop","Filled the requester and model","Left submit to you"]});requestForm("laptop",Object.assign({_for:PU},m));return true}
  if(/contract repository.*access|access.*contract repository|need access to the (contract|repo)/i.test(q)){go("svc_cat");say(q,{t:"Opening <b>Access to the Contract Repository</b>. Your manager and the data owner approve, usually within one business day.",steps:["Matched the catalog item","Prepared the form"]});requestForm("access_repo",{_for:PU});return true}
  if(/who('s| is| are)?.{0,12}on.?call|on.?call (now|today|tonight|this week)/i.test(q)){go("svc_oncall");say(q,{t:`On call now: Service desk <b>${effNow("sd",0)}</b> (backup ${effNow("sd",1)}), Platform <b>${effNow("pe",0)}</b> (backup ${effNow("pe",1)}), Data and search <b>${effNow("ds",0)}</b> (backup ${effNow("ds",1)}). Hand-off is Monday at 08:00. ${detect().length} coverage problems need attention in the next six weeks.`,steps:["Read the rotation for this week","Applied overrides","Scanned six weeks for gaps"]});return true}
  if(/(complian|true.?up|exposure|over.?licen|entitle).{0,30}licen[cs]|licen[cs].{0,30}(complian|true.?up|exposure|enough)|are we compliant/i.test(q)){syncMetrics();const ex=LIC.reduce((a,l)=>a+expo(l),0),ov=LIC.filter(l=>l.asg>l.ent);go("svc_asset");say(q,{t:ov.length?`Not quite. ${ov.map(l=>l.n+" is "+(l.asg-l.ent)+" over").join(", ")}. True-up exposure is about <b>${money(ex)}</b>. Reclaiming licences unused for 90 days would clear it.`:"Yes. Every title is inside its entitlement, so true-up exposure is $0.",steps:["Compared entitled with assigned for 7 titles","Priced the gap at list price","Looked for unused assignments"]});return true}
  if(/(sla|slas).{0,30}(breach|risk|attain|miss)|breach(ing)?|about to breach/i.test(q)){const fc=forecast().filter(x=>x.risk>=1);go("svc_sla");say(q,{t:`${fc.length} open items are forecast to breach: ${fc.slice(0,3).map(x=>x.id).join(", ")}. SLA attainment is ${slaTotals().att.toFixed(1)}% against a 95% goal.`,steps:["Forecast each open item from time used and median remaining work","Checked vendor clocks"]});return true}
  if(/notification|quiet hours|digest|delivery log/i.test(q)){go("svc_notify");say(q,{t:`Delivery rate is ${(PIPE.ok/(PIPE.ok+PIPE.fail)*100).toFixed(1)}%. ${LOG.filter(l=>l.st==="Failed").length} recent failures need attention, mostly contact data.`,steps:["Read the delivery log","Grouped failures by cause"]});return true}
  if(/self.?service|deflection|virtual agent|portal/i.test(q)){go("svc_portal");say(q,{t:`Self-service deflection is ${METRICS.m_deflect.cur}% against a 55% goal. Try the Virtual Agent on the page.`,steps:["Read this month's chats and searches"]});return true}
  if(/my requests|waiting on (my )?approval|status of my (request|laptop|report)/i.test(q)){go("svc_req");say(q,{t:`${REQS.filter(r=>r.st==="Awaiting approval").length} requested items are waiting on approval; Avery Chen holds ${REQS.filter(r=>r.appr.some(a=>a.st==="Pending"&&a.who==="Avery Chen")).length} of them.`,steps:["Read approvals on every open request"]});return true}
  return false});
